using System;using System.Text.Json;using Mxm.Replay;
string line;var s=new StreamKernel();while((line=Console.ReadLine())!=null){using var d=JsonDocument.Parse(line);var r=d.RootElement;string op=r.GetProperty("op").GetString();if(op=="new")s=new StreamKernel();else if(op=="reset")s.Reset();else if(op=="tick")s.Push(r.GetProperty("side").GetString(),r.GetProperty("time").GetInt64(),r.GetProperty("raw").GetInt64());else if(op=="snapshot")Console.WriteLine(JsonSerializer.Serialize(s.Snapshot(r.GetProperty("now").GetInt64(),r.GetProperty("gap").GetBoolean())));else throw new Exception("OP");}
